usage=subprocess.check_output(['du','-x','-s','-B1',str(root)],text=True);v={'status':'PASS_NO_OWNED_LIVE_PROCESS_OR_MOUNT','owned_alive':owned_alive,'mounts':mounts,'old_cohort':old,'real_exit_receipts':exitfiles,'allocated_bytes_du':usage,'free_bytes':os.statvfs(root).f_bavail*os.statvfs(root).f_frsize,'note':'Moose mount wait exit1 is a retained cleanup FAIL despite process/mount gone'}
